// Filtrar citas que necesitan recordatorio
const now = new Date();
const appointments = $input.all();
const needsReminder = [];

for (const item of appointments) {
  const apt = item.json;
  const appointmentDate = new Date(apt.fecha_cita);
  const hoursUntil = (appointmentDate - now) / (1000 * 60 * 60);

  // Recordatorio 24 horas antes
  if (hoursUntil >= 23 && hoursUntil <= 25 && apt.recordatorio_enviado !== '24h') {
    needsReminder.push({ ...apt, reminderType: '24h', hoursUntil: Math.round(hoursUntil) });
  }

  // Recordatorio 2 horas antes
  if (hoursUntil >= 1.5 && hoursUntil <= 2.5 && apt.recordatorio_enviado !== '2h') {
    needsReminder.push({ ...apt, reminderType: '2h', hoursUntil: Math.round(hoursUntil) });
  }

  // Solicitud de reseña 2 horas DESPUÉS de la cita
  if (hoursUntil >= -3 && hoursUntil <= -1 && apt.recordatorio_enviado !== 'review') {
    needsReminder.push({ ...apt, reminderType: 'review', hoursUntil: Math.round(hoursUntil) });
  }
}

return needsReminder.map(r => ({ json: r }));

// Generar mensaje de recordatorio según tipo
const apt = $json;
let message = '';

if (apt.reminderType === '24h') {
  message = `Hola ${apt.paciente} 👋

Te recordamos que mañana tienes tu cita en *[NOMBRE_CLINICA]*:

📅 *${apt.fecha_cita}*
🦷 Servicio: ${apt.servicio}
📍 [DIRECCION_CLINICA]

Si necesitas cambiar o cancelar, responde este mensaje. ¡Hasta mañana! 😊`;
} else if (apt.reminderType === '2h') {
  message = `Hola ${apt.paciente} ⏰

¡Tu cita es en aproximadamente 2 horas!

📅 *${apt.fecha_cita}*
📍 [DIRECCION_CLINICA]

Te esperamos. Si tienes alguna pregunta de último momento, aquí estoy. ¡Nos vemos pronto! 🙂`;
} else if (apt.reminderType === 'review') {
  message = `Hola ${apt.paciente} 😊

Esperamos que tu cita de hoy haya sido excelente. Nos encantaría saber cómo te sentiste.

¿Podrías dejarnos una reseña rápida en Google? Solo toma 1 minuto y nos ayuda mucho:
👉 [LINK_GOOGLE_REVIEWS]

¡Muchas gracias y hasta pronto! 🙏`;
}

return [{ json: { ...apt, reminderMessage: message } }];
